import { randomUUID } from 'node:crypto';
import pg from 'pg';
import { describe, expect, it } from 'vitest';
import { planMigrations } from '../../tools/migrate.mjs';
import { applyIsolatedTestPlan } from './isolated-postgres-plan';
import { seedTeacher } from '../portal/helpers';
import { PgProjectRepository } from '../../contexts/projects/infrastructure/pg-project.repository';

// Only disposable databases are used. The old generic immutable revision is
// generated by the real pre-fix publisher, never by disabling its triggers.
describe('0285 existing public author name forward upgrade', () => {
  it('repairs old public projections without republishing or altering frozen rows and preserves restricted access', async () => {
    const source = process.env.TEST_DATABASE_URL;
    const appSource = process.env.APP_TEST_DATABASE_URL;
    if (
      !source ||
      !appSource ||
      !new URL(source).pathname.endsWith('_test') ||
      new URL(appSource).pathname !== new URL(source).pathname
    )
      throw Error('Same isolated admin/app test database required');
    const database = 'asa_author_' + randomUUID().replaceAll('-', '') + '_test';
    const owner = new pg.Client({ connectionString: source });
    let created = false;
    let admin: pg.Pool | undefined;
    let runtime: pg.Pool | undefined;
    try {
      await owner.connect();
      await owner.query('CREATE DATABASE "' + database + '"');
      created = true;
      const target = new URL(source);
      target.pathname = '/' + database;
      const appTarget = new URL(appSource);
      appTarget.pathname = '/' + database;
      admin = new pg.Pool({ connectionString: target.href, max: 2 });
      runtime = new pg.Pool({ connectionString: appTarget.href, max: 2 });
      const plan = planMigrations();
      const prefix = plan.filter((entry) => Number(entry.version) <= 284);
      const complete = plan.filter((entry) => Number(entry.version) <= 285);
      const migration = await admin.connect();
      try {
        await applyIsolatedTestPlan(migration, prefix);
        const teacher = await seedTeacher(admin, 'author-name-upgrade');
        const identity = (
          await admin.query(
            'SELECT principal_id,account_id FROM legacy_user_account_links WHERE tenant_id=$1 AND user_id=$2',
            [teacher.tenantId, teacher.teacherId],
          )
        ).rows[0];
        await admin.query(
          "UPDATE profiles SET display_name='Северный мастер',visibility='private' WHERE account_id=$1",
          [identity.account_id],
        );
        const repo = new PgProjectRepository(runtime);
        const actor = { principalId: identity.principal_id as string, userId: teacher.teacherId };
        const project = await repo.createWithDraft({
          tenantId: teacher.tenantId,
          scope: 'personal',
          classroomId: null,
          actor,
          moduleKey: 'electronics',
          title: 'Existing named project',
          idempotencyKey: randomUUID(),
          requestFingerprint: randomUUID().replaceAll('-', '').repeat(2),
          initialDocument: { schemaVersion: 1, components: [], connections: [] },
          initialPreview: null,
        });
        if (project.kind !== 'created') throw Error('Fixture project not created');
        await repo.saveSnapshot({
          tenantId: teacher.tenantId,
          actor,
          projectId: project.project.id,
          sourceRevision: 1,
          image: {
            bytes: new Uint8Array(64).fill(17),
            contentType: 'image/png',
            width: 16,
            height: 16,
          },
        });
        const published = (
          await runtime.query('SELECT project_publication_publish($1,$2) AS value', [
            identity.principal_id,
            project.project.id,
          ])
        ).rows[0].value.publication;
        const read = () =>
          runtime!.query('SELECT * FROM public_projects_read($1,NULL,NULL,1,0)', [
            published.publicationId,
          ]);
        expect((await read()).rows[0].author_label).toBe('Автор проекта');
        const frozen = async () =>
          (
            await admin!.query(
              `SELECT to_jsonb(revision) AS revision,to_jsonb(version) AS version FROM project_publication_revisions revision JOIN project_versions version ON version.id=revision.project_version_id WHERE revision.id=$1`,
              [published.revisionId],
            )
          ).rows;
        const before = await frozen();
        const history = (
          await admin.query('SELECT version,name,checksum FROM schema_migrations ORDER BY version')
        ).rows;
        expect(complete.at(-1)?.file).toBe('0285_public_project_author_name.sql');
        expect(await applyIsolatedTestPlan(migration, complete)).toBe(1);
        expect(await applyIsolatedTestPlan(migration, complete)).toBe(0);
        expect(
          (
            await admin.query(
              "SELECT version,name,checksum FROM schema_migrations WHERE version<>'0285' ORDER BY version",
            )
          ).rows,
        ).toEqual(history);
        expect((await read()).rows[0]).toMatchObject({
          author_label: 'Северный мастер',
          revision_id: published.revisionId,
        });
        expect(await frozen()).toEqual(before);
        await expect(
          runtime.query('SELECT project_publication_author_label($1,$2)', [
            identity.principal_id,
            'ignored',
          ]),
        ).rejects.toMatchObject({ code: '42501' });
        await expect(runtime.query('SELECT display_name FROM profiles')).rejects.toMatchObject({
          code: '42501',
        });
        await expect(
          runtime.query('SELECT admin_publications_list($1,0,20)', [identity.principal_id]),
        ).rejects.toMatchObject({ code: '42501' });
        await admin.query("UPDATE accounts SET email_verification_state='verified' WHERE id=$1", [
          identity.account_id,
        ]);
        const adminIdentity = await admin.query(
          "INSERT INTO capability_grants(account_id,capability,state,policy_version,granted_by) VALUES($1,'platform_admin','verified','author-name-test','admin') RETURNING account_id",
          [identity.account_id],
        );
        expect(adminIdentity.rowCount).toBe(1);
        const listed = (
          await runtime.query('SELECT admin_publications_list($1,0,20) AS value', [
            identity.principal_id,
          ])
        ).rows[0].value;
        expect(
          listed.items.find(
            (item: { publicationId: string }) => item.publicationId === published.publicationId,
          ).authorLabel,
        ).toBe('Северный мастер');
        await runtime.query('SELECT project_publication_revoke($1,$2)', [
          identity.principal_id,
          project.project.id,
        ]);
        expect((await read()).rows).toEqual([]);
        expect(await frozen()).toEqual(before);
      } finally {
        migration.release();
      }
    } finally {
      await runtime?.end();
      await admin?.end();
      if (created) await owner.query('DROP DATABASE "' + database + '"');
      await owner.end();
    }
  }, 180_000);
});
